select case when monthly_fee >= 224 then 'high' when monthly_fee >= 112 then 'mid' else 'low' end as monthly_fee_bucket, sum(monthly_fee) as total_monthly_fee, dense_rank() over (order by sum(monthly_fee) desc) as rnk from subscriptions where customer_id = 35 group by case when monthly_fee >= 224 then 'high' when monthly_fee >= 112 then 'mid' else 'low' end order by 1 desc, 2 desc
